from __future__ import annotations

from lead_models import MergedLead, SalesLead, normalize_email


def _group_by_email(leads: list[SalesLead]) -> dict[str, list[SalesLead]]:
    groups: dict[str, list[SalesLead]] = {}
    for lead in leads:
        groups.setdefault(normalize_email(lead.email), []).append(lead)
    return groups


def _merge_group(email: str, leads: list[SalesLead]) -> MergedLead:
    ordered = sorted(leads, key=lambda lead: (lead.created_minute, lead.lead_id))
    newest = ordered[-1]
    highest_score = max(lead.score for lead in leads)
    activity_count = sum(lead.activity_count for lead in leads)
    return MergedLead(
        lead_id=ordered[0].lead_id,
        email=email,
        name=ordered[0].name,
        first_touch_campaign_source=newest.campaign_source,
        score=highest_score,
        activity_count=activity_count,
        source_lead_ids=tuple(lead.lead_id for lead in ordered),
    )


def _as_dict(lead: MergedLead) -> dict[str, object]:
    return {
        "lead_id": lead.lead_id,
        "email": lead.email,
        "name": lead.name,
        "first_touch_campaign_source": lead.first_touch_campaign_source,
        "score": lead.score,
        "activity_count": lead.activity_count,
        "source_lead_ids": list(lead.source_lead_ids),
    }


def merge_sales_leads(leads: list[SalesLead]) -> dict[str, object]:
    merged: list[dict[str, object]] = []
    audit_events: list[dict[str, object]] = []

    for email, group in _group_by_email(leads).items():
        merged_lead = _merge_group(email, group)
        merged.append(_as_dict(merged_lead))
        audit_events.append(
            {
                "email": email,
                "action": "merged" if len(group) > 1 else "kept_single",
                "source_lead_ids": list(merged_lead.source_lead_ids),
                "first_touch_campaign_source": merged_lead.first_touch_campaign_source,
            }
        )

    return summarize_lead_merges(merged, audit_events)


def summarize_lead_merges(
    merged_leads: list[dict[str, object]],
    audit_events: list[dict[str, object]],
) -> dict[str, object]:
    duplicate_groups = [event for event in audit_events if event["action"] == "merged"]
    return {
        "merged_lead_count": len(merged_leads),
        "duplicate_group_count": len(duplicate_groups),
        "merged_leads": merged_leads,
        "audit_events": audit_events,
    }


class SalesCloudLeadMerger:
    def merge(self, leads: list[SalesLead]) -> dict[str, object]:
        return merge_sales_leads(leads)

