from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class SalesLead:
    lead_id: str
    email: str
    name: str
    created_minute: int
    campaign_source: str
    score: int
    activity_count: int

    def __post_init__(self) -> None:
        if not self.lead_id.strip():
            raise ValueError("lead_id required")
        if "@" not in self.email:
            raise ValueError("email must be valid")
        if not self.name.strip():
            raise ValueError("name required")
        if self.created_minute < 0:
            raise ValueError("created_minute must be non-negative")
        if not self.campaign_source.strip():
            raise ValueError("campaign_source required")
        if self.score < 0:
            raise ValueError("score must be non-negative")
        if self.activity_count < 0:
            raise ValueError("activity_count must be non-negative")


@dataclass(frozen=True)
class MergedLead:
    lead_id: str
    email: str
    name: str
    first_touch_campaign_source: str
    score: int
    activity_count: int
    source_lead_ids: tuple[str, ...]


def normalize_email(email: str) -> str:
    return email.strip().lower()

